window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b16786c576049688"]={"versions": [{"id": "FIG-b16786c576049688", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-RTE-Konfiguration (ECU-Konfigurationsparameter-Definition). Das Diagramm stellt das Metamodell-Mapping zwischen dem AUTOSAR-Software-Component-Template (<code>SWComponentTemplate</code>) und den Konfigurationsparametern für die Auswahl einer konkreten Implementierung (<code>SwcImplementation</code>) für eine Software-Komponenten-Instanz (<code>ComponentPrototype</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Schichten bzw. Kontexte:</p>\n<ol class=\"fig-list\">\n<li><strong>ECU-Konfigurations-Metamodell (obere Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SwComponentInstance : ParamConfContainerDef</code>: Container-Definition mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = *</code>. Besitzt zwei Referenzen (Komposition über <code>+reference</code>):</li>\n<li><code>SoftwareComponentInstanceRef : InstanceReferenceParamDef</code>: Instanzreferenz mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, <code>destinationContext = ComponentPrototype*</code>, <code>destinationType = ComponentPrototype</code>. Verweist per gestricheltem Pfeil auf <code>ComponentPrototype</code>.</li>\n<li><code>ImplementationRef : ForeignReferenceParamDef</code>: Fremdreferenz-Definition mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>, <code>destinationType = SwcImplementation</code>. Verweist per gestricheltem Pfeil auf <code>SwcImplementation</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>SWComponentTemplate (untere Ebene / Paket):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ComponentPrototype</code> («atpPrototype», <code>Identifiable</code>): Ist über die Assoziation <code>«isOfType»</code> typisiert durch <code>ComponentType</code> (<code>+type</code> [1], Prototype [*]).</li>\n<li><code>ComponentType</code> («atpType», <code>ARElement</code>): Basisklasse für Software-Komponententypen.</li>\n<li><code>AtomicSoftwareComponentType</code>: Spezialisiert <code>ComponentType</code>. Steht in 1:<em>-Beziehung zu <code>InternalBehavior</code> (<code>+component</code> [1], [</em>]).</li>\n<li><code>InternalBehavior</code> (<code>ARElement</code>): Beschreibt das interne Verhalten; Attribut <code>+ supportsMultipleInstantiation: Boolean</code>. Steht in Beziehung zu <code>SwcImplementation</code> (<code>+behavior</code> [1], [*]).</li>\n<li><code>SwcImplementation</code> (<code>Implementation</code>): Implementierungsartefakt mit Attribut <code>+ requiredRTEVendor: String [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne direkte Laufzeit- oder Sequenzabläufe. Die funktionale Zuordnung erfolgt über die Konfigurationsbindung: Jede <code>SwComponentInstance</code> wählt über die <code>ImplementationRef</code> eine spezifische <code>SwcImplementation</code> für die über <code>SoftwareComponentInstanceRef</code> referenzierte Instanz (<code>ComponentPrototype</code>) eines <code>AtomicSoftwareComponentType</code> aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-RTE-Generatoren und Konfigurationswerkzeuge: Die Bindung einer Implementierung an eine Instanz erfolgt deklarativ über <code>ParamConfContainerDef</code> (<code>SwComponentInstance</code>). <code>SoftwareComponentInstanceRef</code> adressiert die Komponente im Kontext von Prototypen (<code>destinationContext = ComponentPrototype*</code>), während <code>ImplementationRef</code> direkt auf das ARElement <code>SwcImplementation</code> zeigt. Mehrfachinstanziierung wird durch <code>supportsMultipleInstantiation</code> geregelt; Herstellerspezifische RTE-Abhängigkeiten werden über <code>requiredRTEVendor</code> deklariert.</p>"}, {"id": "FIG-7b1b53485863e324", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-RTE-Konfiguration (ECU-Konfigurationsparameter-Definition). Das Diagramm stellt das Metamodell-Mapping zwischen dem AUTOSAR-Software-Component-Template (<code>Software Component template</code>) und den Konfigurationsparametern für die Auswahl einer konkreten Implementierung (<code>SwcImplementation</code>) für eine Software-Komponenten-Instanz (<code>ComponentPrototype</code>) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Schichten bzw. Kontexte:</p>\n<ol class=\"fig-list\">\n<li><strong>ECU-Konfigurations-Metamodell (obere Ebene):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>SwComponentInstance : ParamConfContainerDef</code>: Container-Definition mit Multiplizität <code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 1</code>. Besitzt zwei Referenzen (Komposition über <code>+reference</code>):</li>\n<li><code>SoftwareComponentInstanceRef : InstanceReferenceParamDef</code>: Instanzreferenz mit Attributen <code>destinationType = ComponentPrototype</code>, <code>destinationContext = SoftwareComposition<em> ComponentPrototype</em></code>, <code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 0</code>. Verweist per gestricheltem Pfeil auf <code>ComponentPrototype</code>.</li>\n<li><code>ImplementationRef : ForeignReferenceParamDef</code>: Fremdreferenz-Definition mit Attributen <code>destinationType = SwcImplementation</code>, <code>upperMultiplicity = 1</code>, <code>lowerMultiplicity = 0</code>. Verweist per gestricheltem Pfeil auf <code>SwcImplementation</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Software Component template (untere Ebene / Paket):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>ComponentPrototype</code> («atpPrototype», <code>Identifiable</code>): Ist über die Assoziation <code>«isOfType»</code> typisiert durch <code>ComponentType</code> (<code>+type</code> [1], Prototype [*]).</li>\n<li><code>ComponentType</code> («atpType», <code>ARElement</code>): Basisklasse für Software-Komponententypen.</li>\n<li><code>AtomicSoftwareComponentType</code>: Spezialisiert <code>ComponentType</code>. Steht in 1:<em>-Beziehung zu <code>InternalBehavior</code> (<code>+component</code> [1], [</em>]).</li>\n<li><code>InternalBehavior</code> (<code>ARElement</code>): Beschreibt das interne Verhalten; Attribut <code>+ supportsMultipleInstantiation :Boolean</code>. Steht in Beziehung zu <code>SwcImplementation</code> (<code>+behavior</code> [1], [*]).</li>\n<li><code>SwcImplementation</code> (<code>Implementation</code>): Implementierungsartefakt mit Attribut <code>+ requiredRTEVendor :String [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne direkte Laufzeit- oder Sequenzabläufe. Die funktionale Zuordnung erfolgt über die Konfigurationsbindung: Jede <code>SwComponentInstance</code> wählt über die <code>ImplementationRef</code> eine spezifische <code>SwcImplementation</code> für die über <code>SoftwareComponentInstanceRef</code> referenzierte Instanz (<code>ComponentPrototype</code>) eines <code>AtomicSoftwareComponentType</code> aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Festlegung für AUTOSAR-RTE-Generatoren und Konfigurationswerkzeuge: Die Bindung einer Implementierung an eine Instanz erfolgt deklarativ über <code>ParamConfContainerDef</code> (<code>SwComponentInstance</code>). <code>SoftwareComponentInstanceRef</code> adressiert die Komponente hierarchisch im Kontext von Kompositionen und Prototypen (<code>destinationContext = SoftwareComposition<em> ComponentPrototype</em></code>), während <code>ImplementationRef</code> direkt auf das ARElement <code>SwcImplementation</code> zeigt. Mehrfachinstanziierung wird durch <code>supportsMultipleInstantiation</code> geregelt; herstellerspezifische RTE-Abhängigkeiten werden über <code>requiredRTEVendor</code> deklariert.</p>"}], "trans": [{"from": "FIG-b16786c576049688", "to": "FIG-7b1b53485863e324", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>SoftwareComponentInstanceRef : InstanceReferenceParamDef</code>: <code>destinationContext</code> wurde um <code>SoftwareComposition<em></code> erweitert (<code>destinationContext = SoftwareComposition</em> ComponentPrototype*</code>).</li>\n<li>Paketbezeichnung: Umbenennung von <code>SWComponentTemplate</code> zu <code>Software Component template</code>.</li>\n</ul>"}]};
